
// ── Rues partagées entre deux secteurs ───────────────────────────
// Syntaxe dans le champ "rues" : "Rue Aristide Briand [1,2,4,6,7]"
// Seuls les numéros listés appartiennent au secteur.
function parseRueEntry(entry) {
  const m = (entry || '').match(/^(.*?)\s*\[([^\]]*)\]\s*$/);
  if (!m) return { rue: (entry || '').trim(), numeros: null };
  return {
    rue: m[1].trim(),
    numeros: m[2].split(',').map(x => x.trim()).filter(Boolean)
  };
}

function normRueG(s) {
  return (s || '').toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]/g, '');
}

