// Distance en mètres entre deux points GPS (formule haversine)
function distanceM(lat1, lon1, lat2, lon2) {
  const R = 6371000, toRad = x => x * Math.PI / 180;
  const dLat = toRad(lat2 - lat1), dLon = toRad(lon2 - lon1);
  const a = Math.sin(dLat/2)**2 +
            Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon/2)**2;
  return 2 * R * Math.asin(Math.sqrt(a));
}

// Vérifie si la géolocalisation est disponible
export function geolocDisponible() {
  return 'geolocation' in navigator;
}

// Récupère la position actuelle
export function positionActuelle(options = {}) {
  return new Promise((resolve, reject) => {
    if (!geolocDisponible()) {
      reject(new Error("Géolocalisation non disponible sur cet appareil"));
      return;
    }
    navigator.geolocation.getCurrentPosition(
      pos => resolve({
        lat: pos.coords.latitude,
        lon: pos.coords.longitude,
        precision: Math.round(pos.coords.accuracy)
      }),
      err => {
        const msgs = {
          1: "Accès à la position refusé. Autorise-le dans les réglages.",
          2: "Position indisponible. Vérifie que le GPS est activé.",
          3: "Recherche de position trop longue. Réessaie à l'extérieur."
        };
        reject(new Error(msgs[err.code] || "Erreur de géolocalisation"));
      },
      { enableHighAccuracy: true, timeout: 15000, maximumAge: 5000, ...options }
    );
  });
}

// Cherche les N adresses les plus proches d'une position
// commune : si précisée, limite la recherche à cette commune (plus rapide et pertinent)
export function adressesProches(lat, lon, { commune = null, limite = 3, rayonMax = 300 } = {}) {
  const resultats = [];
  const communes = commune && GEO_ADRESSES[commune]
    ? { [commune]: GEO_ADRESSES[commune] }
    : GEO_ADRESSES;

  for (const [nomCommune, data] of Object.entries(communes)) {
    const rues = data.r;
    for (const [num, rueIdx, aLat, aLon] of data.p) {
      // Filtre grossier avant le calcul exact (optimisation)
      if (Math.abs(aLat - lat) > 0.004 || Math.abs(aLon - lon) > 0.006) continue;
      const d = distanceM(lat, lon, aLat, aLon);
      if (d <= rayonMax) {
        resultats.push({
          numero: num,
          rue: rues[rueIdx],
          commune: nomCommune,
          distance: Math.round(d),
          adresse: `${num} ${rues[rueIdx]}`
        });
      }
    }
  }

  resultats.sort((a, b) => a.distance - b.distance);
  return resultats.slice(0, limite);
}

// Recherche par texte (autocomplétion)
// Retourne les adresses correspondant à une saisie partielle
export function chercherAdresses(saisie, { commune = null, limite = 8 } = {}) {
  const q = (saisie || '').toLowerCase().trim();
  if (q.length < 2) return [];

  // Extraire un éventuel numéro en début de saisie
  const mNum = q.match(/^(\d+[a-z]?)\s*(.*)$/);
  const numCherche = mNum ? mNum[1] : null;
  const texteRue = mNum ? mNum[2] : q;

  const resultats = [];
  const communes = commune && GEO_ADRESSES[commune]
    ? { [commune]: GEO_ADRESSES[commune] }
    : GEO_ADRESSES;

  for (const [nomCommune, data] of Object.entries(communes)) {
    const rues = data.r;
    // Trouver les rues qui correspondent au texte
    const ruesOk = new Set();
    rues.forEach((r, i) => {
      if (!texteRue || r.toLowerCase().includes(texteRue)) ruesOk.add(i);
    });
    if (ruesOk.size === 0) continue;

    for (const [num, rueIdx] of data.p) {
      if (!ruesOk.has(rueIdx)) continue;
      if (numCherche && !num.toLowerCase().startsWith(numCherche)) continue;
      resultats.push({
        numero: num, rue: rues[rueIdx], commune: nomCommune,
        adresse: `${num} ${rues[rueIdx]}`
      });
      if (resultats.length >= limite * 4) break;
    }
  }

  // Trier : numéro exact d'abord, puis par numéro croissant
  resultats.sort((a, b) => {
    const na = parseInt(a.numero) || 9999, nb = parseInt(b.numero) || 9999;
    if (a.rue !== b.rue) return a.rue.localeCompare(b.rue);
    return na - nb;
  });
  return resultats.slice(0, limite);
}

// Statistiques : nombre de foyers d'une rue ou d'une commune
export function nbFoyers(commune, rue = null) {
  const data = GEO_ADRESSES[commune];
  if (!data) return 0;
  if (!rue) return data.p.length;
  const idx = data.r.indexOf(rue);
  if (idx === -1) return 0;
  return data.p.filter(p => p[1] === idx).length;
}

// Liste des numéros d'une rue (pour la liste à cocher)
export function numerosDeRue(commune, rue, restriction = null) {
  const data = GEO_ADRESSES[commune];
  if (!data) return [];
  const cible = normRueG(rue);
  const idx = data.r.findIndex(r => normRueG(r) === cible);
  if (idx === -1) return [];
  let nums = data.p.filter(p => p[1] === idx).map(p => p[0]);
  if (Array.isArray(restriction)) {
    const ok = new Set(restriction.map(normRueG));
    nums = nums.filter(n => ok.has(normRueG(n)));
  }
  return [...new Set(nums)].sort((a, b) => (parseInt(a)||9999) - (parseInt(b)||9999));
}

// Coordonnées GPS des adresses d'une rue (pour surligner sur la mini carte)
export function coordsRue(commune, rue, restriction = null) {
  const data = GEO_ADRESSES[commune];
  if (!data) return [];
  const cible = normRueG(rue);
  const idx = data.r.findIndex(r => normRueG(r) === cible);
  if (idx === -1) return [];
  let pts = data.p.filter(p => p[1] === idx);
  if (Array.isArray(restriction)) {
    const ok = new Set(restriction.map(normRueG));
    pts = pts.filter(p => ok.has(normRueG(p[0])));
  }
  return pts.map(p => ({ numero: p[0], lat: p[2], lon: p[3] }));
}

// Nombre total de boîtes aux lettres d'un secteur (somme de ses rues)
// secteur : objet avec .commune et .rues[]
export function nbFoyersSecteur(secteur) {
  if (!secteur || !secteur.commune) return 0;
  const data = GEO_ADRESSES[secteur.commune];
  if (!data) return 0;
  if (!secteur.rues || secteur.rues.length === 0) return data.p.length;

  // Construire la table : index de rue → liste de numéros autorisés (null = tous)
  const filtre = {};
  for (const entry of secteur.rues) {
    const { rue, numeros } = parseRueEntry(entry);
    const cible = normRueG(rue);
    data.r.forEach((r, i) => {
      if (normRueG(r) !== cible) return;
      if (numeros === null) { filtre[i] = null; }
      else if (filtre[i] !== null) {
        filtre[i] = [...(filtre[i] || []), ...numeros.map(normRueG)];
      }
    });
  }

  let n = 0;
  for (const p of data.p) {
    if (!(p[1] in filtre)) continue;
    const autorises = filtre[p[1]];
    if (autorises === null || autorises.includes(normRueG(p[0]))) n++;
  }
  return n;
}

// Liste les rues d'un secteur avec leur nombre de foyers, triées alphabétiquement
export function ruesDuSecteur(secteur) {
  if (!secteur || !secteur.commune) return [];
  const data = GEO_ADRESSES[secteur.commune];
  if (!data) return [];

  // Filtre par rue, avec numéros autorisés éventuels
  const filtre = {};
  if (secteur.rues && secteur.rues.length > 0) {
    for (const entry of secteur.rues) {
      const { rue, numeros } = parseRueEntry(entry);
      const cible = normRueG(rue);
      data.r.forEach((r, i) => {
        if (normRueG(r) !== cible) return;
        if (numeros === null) filtre[i] = null;
        else if (filtre[i] !== null) filtre[i] = [...(filtre[i] || []), ...numeros.map(normRueG)];
      });
    }
  } else {
    data.r.forEach((_, i) => { filtre[i] = null; });
  }

  const compte = {};
  for (const p of data.p) {
    if (!(p[1] in filtre)) continue;
    const a = filtre[p[1]];
    if (a === null || a.includes(normRueG(p[0]))) compte[p[1]] = (compte[p[1]] || 0) + 1;
  }

  return Object.entries(compte)
    .map(([i, n]) => ({ rue: data.r[i], foyers: n, restriction: filtre[i] }))
    .sort((a, b) => a.rue.localeCompare(b.rue, 'fr'));
}
